`timescale 1ns / 1ps
// Board-clock reset sequencer for the FT601.
// ft_clk is generated by the FT601, so it is not available while the chip
// is held in reset. Sequence:
//   1. Hold ft_reset low for ~1 ms after FPGA config / button press
//   2. Release ft_reset
//   3. Wait ~1 ms for CLK to run
//   4. Release rst_ft (ft_clk domain) through a 3-flop synchronizer
module ft601_reset #(
    parameter integer HOLD_CYCLES = 100000
) (
    input  wire clk_board,
    input  wire rst_n_async,
    input  wire ft_clk,
    output wire ft_reset,
    output wire rst_ft
);

    // Active-low button -> active-high async, then 2-flop on board clock.
    wire rst_async = ~rst_n_async;

    (* ASYNC_REG = "TRUE" *) reg [1:0] btn_sync;
    always @(posedge clk_board or posedge rst_async) begin
        if (rst_async)
            btn_sync <= 2'b11;
        else
            btn_sync <= {btn_sync[0], 1'b0};
    end

    localparam ST_HOLD   = 2'd0;
    localparam ST_WAIT   = 2'd1;
    localparam ST_RUN    = 2'd2;

    reg [1:0]  state;
    reg [16:0] timer;
    reg        ft_reset_r;
    reg        rst_hold;

    always @(posedge clk_board) begin
        if (btn_sync[1]) begin
            state      <= ST_HOLD;
            timer      <= 17'd0;
            ft_reset_r <= 1'b0;
            rst_hold   <= 1'b1;
        end else begin
            case (state)
                ST_HOLD: begin
                    ft_reset_r <= 1'b0;
                    rst_hold   <= 1'b1;
                    if (timer >= HOLD_CYCLES[16:0]) begin
                        state <= ST_WAIT;
                        timer <= 17'd0;
                    end else
                        timer <= timer + 1'b1;
                end
                ST_WAIT: begin
                    ft_reset_r <= 1'b1;
                    rst_hold   <= 1'b1;
                    if (timer >= HOLD_CYCLES[16:0]) begin
                        state <= ST_RUN;
                        timer <= 17'd0;
                    end else
                        timer <= timer + 1'b1;
                end
                default: begin
                    ft_reset_r <= 1'b1;
                    rst_hold   <= 1'b0;
                end
            endcase
        end
    end

    assign ft_reset = ft_reset_r;

    (* ASYNC_REG = "TRUE" *) reg [2:0] rst_ft_sync;
    always @(posedge ft_clk or posedge rst_hold) begin
        if (rst_hold)
            rst_ft_sync <= 3'b111;
        else
            rst_ft_sync <= {rst_ft_sync[1:0], 1'b0};
    end

    assign rst_ft = rst_ft_sync[2];

endmodule
